// ============================================================
// SAFETY NET BAIC CENTRAL - Garantiza la ejecucion de close_conversation
// Capas: (1) tag alert sin tool, (2) despedida del usuario sin tool,
// (3) palabras clave de cierre en la respuesta -> verificacion con LLM.
// Excepcion: Fase 1B (contacto directo) NUNCA cierra ni envia alert.
// ============================================================
const MAX_RECOVERIES = 2; // reintentos maximos por ejecucion (anti-loop)

const agentOutput = $input.first().json;
const outputText = String(agentOutput.output || '');
const steps = agentOutput.intermediateSteps || [];

const trigger = $('When chat message received').first().json;
const userText = String(trigger.chatInput || '');
const convId = String(trigger.idConversation || trigger.sessionId || 'sin_id');

// Estado por conversacion (persiste entre ejecuciones de produccion)
const sd = $getWorkflowStaticData('global');
sd.closed = sd.closed || {};
sd.directContact = sd.directContact || {};
const now = Date.now();
const TTL = 7 * 24 * 60 * 60 * 1000;
for (const store of [sd.closed, sd.directContact]) {
  for (const k of Object.keys(store)) {
    if (now - store[k] > TTL) delete store[k];
  }
}

const pass = (extra = {}) => [{ json: { action: 'passthrough', output: outputText, intermediateSteps: steps, ...extra } }];
const recover = (reason) => [{ json: { action: 'force_recovery', reason, output: outputText, intermediateSteps: steps } }];
const canRetry = $runIndex < MAX_RECOVERIES;

// Despedida del usuario: mensaje corto, sin pregunta, hecho solo de palabras de despedida
function isUserFarewell(text) {
  if (!text || text.includes('?')) return false;
  const t = text.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t) return false;
  const tokens = t.split(' ');
  if (tokens.length > 8) return false;
  const ANCHOR_TOKEN = /^(adio+s+|ch?a+u+|ch?ao+|bye+|gracia+s+|cuidate)$/;
  const ANCHOR_PHRASE = /\b(hasta (luego|pronto|manana)|nos vemos|nada mas|eso es todo|me voy)\b/;
  const FILLER = new Set(['hasta','luego','pronto','manana','nos','vemos','nada','mas','eso','es','todo','me','voy','muchas','mil','muy','mucho','ok','oka','okey','listo','perfecto','genial','excelente','bueno','buenas','tardes','noches','dias','buen','dia','tarde','noche','igualmente','igual','abrazo','que','andes','bien','estes','y','vos','tambien','a','todos','la','proxima','ya','esta','no','un','por','ahora','amable','atencion','tu','su','ayuda','informacion','el','tiempo']);
  const hasAnchor = tokens.some(tk => ANCHOR_TOKEN.test(tk)) || ANCHOR_PHRASE.test(t);
  const allKnown = tokens.every(tk => ANCHOR_TOKEN.test(tk) || FILLER.has(tk));
  return hasAnchor && allKnown;
}

// Se ejecuto close_conversation (sin error) en esta corrida del agente?
const closeStep = steps.find(s => /^close_con?versation/i.test(String((s.action && s.action.tool) || '')) && !/"error"/i.test(String(s.observation || '')));
if (closeStep) sd.closed[convId] = now;
const alreadyClosed = !!sd.closed[convId];
const hasAlertTag = /【alert:\s*\"?close_conversation\"?】/i.test(outputText);

if (closeStep) return pass({ close_executed: true });

// Fase 1B: contacto directo -> NO se cierra ni se envia alert
const isDirectContact = /tel[eé]fono principal de BAIC/i.test(outputText) && !hasAlertTag;
if (isDirectContact) { sd.directContact[convId] = now; return pass(); }
if (sd.directContact[convId]) return pass();

// Conversacion ya cerrada antes: solo responder amablemente, no duplicar
if (alreadyClosed) return pass();

// CAPA 1: el bot mando el alert de cierre pero no ejecuto la tool
if (hasAlertTag) return canRetry ? recover('alert_sin_tool') : pass({ warning: 'alert_sin_tool' });

// CAPA 2: el usuario se despidio y no se ejecuto la tool
if (isUserFarewell(userText)) return canRetry ? recover('despedida_sin_close_conversation') : pass({ warning: 'despedida_sin_close_conversation' });

// CAPA 3: la respuesta del bot parece un cierre -> verificar con LLM
const CLOSING_KEYWORDS = /un asesor te contactar[aá]|ya envi[eé] tu solicitud|ya le avis[eé] al equipo|gracias por tu inter[eé]s|hasta luego|hasta pronto|fue un placer|chau|bye/i;
if (canRetry && CLOSING_KEYWORDS.test(outputText)) {
  return [{ json: { action: 'needs_llm_verification', output: outputText, intermediateSteps: steps } }];
}

return pass();

